def enumerate_covers(A: Poly, B: Poly, *, window: float, tol: float=0.0, require_in_segment: bool=True, cone_tol: float | None=None, seg_tol: float | None=None) -> list[Cover]:
    """枚举有效盖；window 是 |gap| 的显式距离域窗，seg_tol 是边端外的显式长度域窗（默认 tol）。
    距离窗/边内/法锥全部精确平方比较，窗口不抬到舍入地板；VV 仅收活跃盖。"""
    st = tol if seg_tol is None else seg_tol
    out = []
    for ia in range(len(A)):
        for jb in range(len(B)):
            if not _feature_in_gap_window('VE', ia, jb, A, B, window):
                continue
            c = ve_cover(A, ia, B, jb, tol, cone_tol)
            if c is not None and (not require_in_segment or _in_segment_exact(A[ia], *edge(B, jb), st)):
                out.append(c)
    for ka in range(len(A)):
        for ib in range(len(B)):
            if not _feature_in_gap_window('EV', ka, ib, A, B, window):
                continue
            c = ev_cover(A, ka, B, ib, tol, cone_tol)
            if c is not None and (not require_in_segment or _in_segment_exact(B[ib], *edge(A, ka), st)):
                out.append(c)
    for ia in range(len(A)):
        for jb in range(len(B)):
