def sum_units_positive(a, b, la, lb):
    if min(a, b) >= 0:
        return max(a, b) > 0
    if max(a, b) <= 0:
        return False
    cmp = a * a * lb - b * b * la
    return cmp > 0 if a > 0 else cmp < 0

def strict_feasible(rows):
    for x in (-1, 1):
        lowers = []
        uppers = []
        valid = True
        for a, b in rows:
            if b > 0:
                lowers.append(-a * x / b)
            elif b < 0:
                uppers.append(-a * x / b)
            elif a * x <= 0:
                valid = False
                break
        if valid and (not lowers or not uppers or max(lowers) < min(uppers)):
            return True
    return all((b > 0 for a, b in rows)) or all((b < 0 for a, b in rows))

def inside(p, P):
    winding = 0
    for i, a in enumerate(P):
        b = P[(i + 1) % len(P)]
        if on(a, b, p):
            return 0
        if a[1] <= p[1] < b[1] and orient(a, b, p) > 0:
            winding += 1
        if b[1] <= p[1] < a[1] and orient(a, b, p) < 0:
            winding -= 1
    return 1 if winding else -1

