        for inside, a, b in (((i, j - 1), (i, j), (i + 1, j)), ((i + 1, j), (i + 1, j), (i + 1, j + 1)), ((i, j + 1), (i + 1, j + 1), (i, j + 1)), ((i - 1, j), (i, j + 1), (i, j))):
            if inside not in cells:
                if a in nxt:
                    return None
                nxt[a] = b
    start = min(nxt)
    ring, p = ([start], nxt[start])
    while p != start:
        ring.append(p)
