def load_step_geometries(verts_csv: Path, *, dup_tol: float=1e-12) -> dict[int, StepGeometry]:
    by: dict[int, dict[int, list[tuple[int, tuple[float, float]]]]] = defaultdict(lambda: defaultdict(list))
