def _prism(eps, translation=F(0), scale=F(1), floating=False):
    ring = [(F(0), F(0)), (F(2), F(0)), (F(2), F(1)), (F(1), F(1) - eps), (F(0), F(1))]
    n = len(ring)
    verts = [(translation + scale * x, scale * y, scale * z) for y in (F(-1), F(1)) for x, z in ring]
    if floating:
        verts = [tuple(map(scalar_exact, p)) for p in verts]
    faces = [tuple(range(n)), tuple(reversed(range(n, 2 * n)))]
    faces += [(i, n + i, n + (i + 1) % n, (i + 1) % n) for i in range(n)]
    return G.Polyhedron(verts, faces)

def vv_cover(A: Poly, ia: int, B: Poly, jb: int, tol: float=0.0, cone_tol: float | None=None) -> Cover | None:
    """VV 锥交有效性精确：两个非退化凸锥的相对内部相交。活跃性用严格精确符号；
    方向恰在锥边界时不标 strict（该处由 VE/EV 表示）；仅 a == b 才是重合。
    显式 tol/cone_tol 只放宽 window_active，strict 仍报告精确严格性。"""
    alo, ahi = _raw_cone(A, ia)
    blo, bhi = _raw_cone(B, jb)
    if cross2_sign(alo, ahi) <= 0 or cross2_sign(blo, bhi) <= 0:
        return None
    alo, ahi = (neg(alo), neg(ahi))
    rays = (alo, ahi, blo, bhi)
    if not any((_open_cone(alo, ahi, add(u, v)) and _open_cone(blo, bhi, add(u, v)) for k, u in enumerate(rays) for v in rays[k + 1:])):
        return None
    a, b = (A[ia], B[jb])
    d = _vsub(_fr(a), _fr(b))
    if d == (0, 0):
        return Cover('VV', ia, jb, None, 0.0, None, a, True, a, b)
    active = _open_cone(alo, ahi, d) and _open_cone(blo, bhi, d)
    w2 = _angle_window2(tol, cone_tol, rays)
    expanded = w2 > 0 and _cone_accepts(alo, ahi, d, w2) and _cone_accepts(blo, bhi, d, w2)
    return Cover('VV', ia, jb, unit(d), norm(d), None, a, active, a, b, expanded)

def first_entrance(A: Poly, B: Poly, x0: Point, d: Point, *, tol: float=0.0, t_max: float=float('inf')) -> Entrance2:
    """沿 x(t)=x0+t·d 的精确闭集首入；tol 只作 near_labels 的长度报告窗，不改答案。"""
    if d[0] == 0 and d[1] == 0:
        raise ValueError('direction must be nonzero')
    if tol < 0 or t_max < 0:
        raise ValueError('tol and t_max must be nonnegative')
    r = _floor(A, B, x0, d)
    if convexity_violation(A) is None and convexity_violation(B) is None:
        if membership_exact(A, B, x0) == 1:
            return shortest_exit(A, B, x0, tol=tol)
        return _first_entrance_convex(A, B, x0, d, tol, r, t_max)
    if entrance_membership_exact(A, B, x0) == 1:
        return shortest_exit(A, B, x0, tol=tol)
    return _first_entrance_concave(A, B, x0, d, tol, r, t_max)

def _extrude(ring):
    n = len(ring)
    vertices = [(F(x), F(y), F(z)) for z in (0, 1) for x, y in ring]
    faces = [tuple(reversed(range(n))), tuple(range(n, 2 * n))]
    faces += [(i, (i + 1) % n, (i + 1) % n + n, i + n) for i in range(n)]
    return Polyhedron(vertices, faces)

