def _join(*shells):
    verts, faces = ([], [])
    for shell in shells:
        offset = len(verts)
        faces.extend((tuple((offset + i for i in face)) for face in shell.faces))
        verts.extend(shell.verts)
    return G.Polyhedron(verts, faces)

